//c2pa.org/manifest\"><style>\n.sme{--sm-speed:1} .sme .bq{animation-duration:calc(8s / var(--sm-speed));animation-iteration-count:infinite;transform-box:view-box}\n.sme .tilt{animation-name:sm-pour_lightblue-tilt;animation-timing-function:ease-in-out;transform-origin:268px 136px}\n@keyframes sm-pour_lightblue-tilt{0%,4%{transform:rotate(0)}16%,54%{transform:rotate(38deg)}68%,100%{transform:rotate(0)}}\n.sme .stream{animation-name:sm-pour_lightblue-stream;animation-timing-function:linear}\n@keyframes sm-pour_lightblue-stream{0%,14%{opacity:0;transform:scaleY(.05)}18%{opacity:1;transform:scaleY(1)}52%{opacity:1;transform:scaleY(1)}58%,100%{opacity:0;transform:scaleY(.05)}}\n.sme .flick{animation:sm-pour_lightblue-flick calc(.18s / var(--sm-speed)) linear infinite alternate} @keyframes sm-pour_lightblue-flick{from{opacity:.75}to{opacity:1}}\n.sme .index{animation-name:sm-pour_lightblue-index;animation-timing-function:ease-in-out}\n@keyframes sm-pour_lightblue-index{0%,70%{transform:translateX(0)}96%,100%{transform:translateX(96px)}}\n.sme .spark{animation:sm-pour_lightblue-spark calc(.9s / var(--sm-speed)) ease-out infinite} @keyframes sm-pour_lightblue-spark{0%{transform:translate(0,0);opacity:0}15%{opacity:1}100%{transform:translate(var(--dx),var(--dy));opacity:0}}\n.sme .fume{animation:sm-pour_lightblue-fume calc(2.4s / var(--sm-speed)) ease-out infinite} @keyframes sm-pour_lightblue-fume{0%{transform:translate(0,0) scale(.5);opacity:0}20%{opacity:.45}100%{transform:translate(-14px,-70px) scale(1.8);opacity:0}}\n.sme .glowcup{animation-name:sm-pour_lightblue-cup;animation-timing-function:linear} @keyframes sm-pour_lightblue-cup{0%,16%{opacity:0}22%,60%{opacity:1}70%,100%{opacity:0}}\n.sme.is-stopped .bq,.sme.is-stopped .flick,.sme.is-stopped .spark,.sme.is-stopped .fume{animation-play-state:paused}\n.sme.is-offline .bq,.sme.is-offline .flick,.sme.is-offline .spark,.sme.is-offline .fume{animation:none} .sme.is-offline .stream,.sme.is-offline .glowcup,.sme.is-offline