/* ---- runtime ---- */
Object.assign(SMLIB_SRC, DL_SRC);
const DL_DEFAULT = 'lightblue';
const dlIs = id => !!DL_PAINT[id];
const dlPaintOf = (id, paint) => (DL_PAINT[id][paint] ? paint : DL_PAINT[id][DL_DEFAULT] ? DL_DEFAULT : Object.keys(DL_PAINT[id])[0]);
// Digital Loop drawings: colour = root CSS variables; still = stopped + no motion; fault = the drawing's own alarm state
const smlibUrl0 = smlibUrl;
smlibUrl = function (id, v, pal, paint) {
  if (!dlIs(id)) return smlibUrl0(id, v, pal, paint);
  const pk = dlPaintOf(id, paint),
    key = 'dl:' + id + ':' + v + ':' + pk;
  if (SMLIB_URL[key]) return SMLIB_URL[key];
  let s = SMLIB_SRC[id] || '';
  const st = DL_PAINT[id][pk];
  if (st) s = s.replace(/style="[^"]*--sm-body:[^"]*"/, 'style="' + st + '"');
  if (v === 'fault') s = s.replace(/(class="sme[^"]*?)\bis-running\b/, '$1is-running is-alarm');
  if (v === 'still') s = s.replace(/(class="sme[^"]*?)\bis-running\b/, '$1is-stopped').replace(/(<svg[^>]*>)/, '$1' + SMLIB_STOP);
  return (SMLIB_URL[key] = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(s));
};
